const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const icon=k=>{if(!paths[k])throw Error('Unknown icon: '+k);return '<svg class="ui-icon" data-icon="'+k+'" viewBox="0 0 24 24" aria-hidden="true" focusable="false">'+paths[k]+'</svg>'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,action,kind='',ico='')=>`<button class="control ${kind}" ${action}>${ico?icon(ico):''}${text}</button>`;
const goto=(text,route,kind='',ico='')=>btn(text,`data-go="${route}"`,kind,ico);
const modalbtn=(text,name,kind='',ico='')=>btn(text,`data-modal="${name}"`,kind,ico);
const person=(name,tone='')=>`<span class="person"><span class="avatar ${tone}">${name[0]}</span>${name}</span>`;
const badge=(text,type='')=>`<span class="badge ${type}">${text}</span>`;
const toggle=(on=true)=>`<button class="toggle ${on?'on':''}" role="switch" aria-checked="${on}" aria-label="切换设置"></button>`;
const check=(on=true)=>`<input type="checkbox" class="check" ${on?'checked':''} aria-label="选择">`;
let route='home',closed=false,returnTo='records',selectedField='报销金额',selectedNode='财务审批',activeFilter='',hiddenColumns=new Set(),filterRows=1,recordDirty=false;
const screenNames={home:'工作台',apps:'应用中心',application:'人事管理',records:'请假申请',record:'记录详情','new-record':'新建报销','form-builder':'表单设计',flows:'流程管理','flow-builder':'流程设计',inbox:'待我审批',approval:'审批详情',started:'我发起的',history:'变更记录',permissions:'菜单权限','data-permissions':'数据权限','app-settings':'应用设置',members:'成员管理',departments:'部门分组',identities:'身份模板','permission-templates':'权限模板',invitations:'邀请码',audit:'审计日志',login:'登录',register:'注册'};
window.PROTOTYPE_SCREENS=Object.entries(screenNames).map(([id,title])=>({id,title}));
const records=[['家庭事务，申请事假','梁宇凡','事假','10/08 – 10/09','2 天','审批中'],['国庆后调休申请','陈思远','调休','10/09','1 天','审批中'],['个人年假申请','林晓','年假','10/12 – 10/14','3 天','审批中'],['就医复诊','许知言','病假','10/08','0.5 天','审批中'],['陪同家人办理事务','周予安','事假','09/29','1 天','已通过'],['年度假期安排','陈思远','年假','09/25 – 09/28','2 天','已通过'],['周末加班调休','梁宇凡','调休','09/24','1 天','已通过'],['个人事务请假','林晓','事假','09/23','0.5 天','已通过'],['家中事务处理','许知言','事假','09/21 – 09/22','2 天','已通过'],['休假申请','周予安','年假','09/18','1 天','已通过']];
const members=['梁宇凡','陈思远','林晓','许知言','周予安','沈以宁','顾言','苏晓','陆明','程悦'];
function nav(text,ico,dest,active=false,child=false){return `<button class="nav ${active?'current':''} ${child?'child':''}" data-go="${dest}" title="${text}" aria-label="${text}">${child?'':icon(ico)}<span class="nav-label">${text}</span>${dest==='inbox'?'<span class="count">8</span>':''}</button>`}
function sidebar(){let editor=['form-builder','flow-builder'].includes(route),admin=['members','departments','identities','permission-templates','invitations','audit'].includes(route);return `<div class="brand"><button class="brand-toggle" id="openSidebar" title="${closed?'展开侧边栏':'WeaveOS'}" aria-label="${closed?'展开侧边栏':'WeaveOS'}" aria-expanded="${!closed}" ${closed?'':'disabled tabindex="-1"'}><span class="logo">w</span><span class="expand-glyph">${icon('panel')}</span></button><span class="brand-word">WeaveOS</span><button class="iconbutton" id="closeSidebar" aria-label="收起侧边栏">${icon('panel')}</button></div>${editor?palette():`<div class="workspace"><span class="mark">${icon('layers')}</span><div><strong>Weave 工作空间</strong><div class="muted">个人工作空间</div></div><span class="push muted">${icon('chevrons')}</span></div>${nav('工作台','home','home',route==='home')}${nav('待办事项','inbox','inbox',route==='inbox'||route==='approval')}${nav('我发起的','clock','started',route==='started')}<div class="section"><span>${admin?'管理':'应用'}</span><button class="iconbutton" data-go="apps" aria-label="应用中心">${icon('plus')}</button></div>${admin?nav('成员管理','users','members',route==='members')+nav('部门分组','folder','departments',route==='departments')+nav('身份模板','shield','identities',route==='identities')+nav('权限模板','lock','permission-templates',route==='permission-templates')+nav('邀请码','key','invitations',route==='invitations')+nav('审计日志','audit','audit',route==='audit'):`${nav('人事管理','users','application',['application','records','record','permissions','data-permissions','app-settings'].includes(route))}${nav('人员档案','file','members',false,true)}${nav('假勤管理','file','records',route==='records',true)}${nav('入离职管理','file','application',false,true)}${nav('财务管理','wallet','new-record',['new-record','flows','history'].includes(route))}${nav('客户管理','briefcase','application')}${nav('全部应用','grid','apps',route==='apps')}<div class="line"></div><div class="section"><span>已收藏</span><button class="iconbutton" data-modal="new-app" aria-label="添加收藏">${icon('plus')}</button></div>${nav('我的报销','file','started')}${nav('客户跟进记录','file','records')}`}` }<div class="footer">${editor?'':nav('设置','settings','members',admin)+nav('帮助中心','help','app-settings')}<button class="profile" id="accountTrigger" aria-label="账户菜单" aria-haspopup="menu" aria-expanded="false" aria-controls="accountMenu"><span class="avatar">梁</span><span class="profile-copy"><strong>梁宇凡</strong><small>空间管理员</small></span><span class="push account-chevron">${icon('chevrons')}</span></button><div class="account-menu" id="accountMenu" popover="auto" role="menu" aria-label="账户菜单"><div class="account-menu-heading"><span class="avatar">梁</span><span><strong>梁宇凡</strong><small>空间管理员</small></span></div><div class="menu-rule"></div><button role="menuitem" data-go="members">${icon('settings')}设置</button><button role="menuitem" data-modal="help">${icon('help')}帮助中心</button><div class="menu-rule"></div><button role="menuitem" data-go="login">${icon('logout')}退出登录</button></div></div>`}
function palette(){if(route==='flow-builder')return `<div class="editor-palette"><div class="palette-tabs"><span class="active">流程节点</span></div><div class="palette-title">基础节点</div><div class="stack">${[['发起人','users'],['审批','shield'],['条件分支','branch'],['结束','check']].map(([t,i])=>`<button class="palette-item" data-add-node="${t}">${icon(i)}<span>${t}</span></button>`).join('')}</div><div class="palette-title">流程设置</div><div class="setting-row">允许撤回 ${toggle()}</div><div class="setting-row">审批通知 ${toggle(false)}</div></div>`;return `<div class="editor-palette"><div class="palette-tabs"><span class="active">字段</span><span>布局</span></div><div class="palette-title">基础字段</div><div class="palette-grid">${[['单行文字','text'],['多行文字','list'],['数字','number'],['金额','wallet'],['日期','calendar'],['单选','check'],['多选','list'],['成员','users'],['部门','folder'],['附件','attach'],['关联记录','link'],['分隔线','minimize']].map(([t,i])=>`<button class="palette-item" draggable="true" data-add-field="${t}">${icon(i)}<span>${t}</span></button>`).join('')}</div><div class="palette-title">最近使用</div><div class="palette-grid"><button class="palette-item" data-add-field="金额">${icon('wallet')}<span>金额</span></button><button class="palette-item" data-add-field="日期">${icon('calendar')}<span>日期</span></button></div></div>`}
function crumbs(){if(route==='home')return ['home','工作台'];if(['apps','application'].includes(route))return ['grid','应用中心',route==='application'?'人事管理':''];if(['members','departments','identities','permission-templates','invitations','audit'].includes(route))return ['settings','管理后台',screenNames[route]];if(['inbox','approval','started'].includes(route))return ['inbox','工作台',screenNames[route]];if(['form-builder','new-record','flow-builder','flows','history'].includes(route))return ['wallet','财务管理','报销申请',screenNames[route]];return ['users','人事管理','假勤管理',screenNames[route]==='请假申请'?'':screenNames[route]]}
function topbar(){const c=crumbs();let editor=['form-builder','flow-builder'].includes(route);return `<header class="top"><div class="crumbs">${icon(c[0])}${c.slice(1).filter(Boolean).map((s,i)=>`${i?'<span class="slash">/</span>':''}<span>${s}</span>`).join('')}</div><div class="actions">${editor?`${btn('撤销','data-undo="true"','','undo')}${modalbtn('预览','preview','','eye')}${btn('保存','data-save="design"','primary')}${btn('退出','data-exit="true"')}`:`<button class="search" data-modal="search">${icon('search')}搜索工作空间<span class="key">⌘ K</span></button><span class="separator"></span><button class="iconbutton" data-go="inbox" aria-label="待办事项">${icon('bell')}</button><button class="iconbutton" data-modal="help" aria-label="帮助">${icon('help')}</button>${modalbtn('分享','share','','share')}`}</div></header>`}
function tabs(){const financial=['flows','history'].includes(route);if(!['records','record','application','flows','permissions','data-permissions','app-settings','history'].includes(route))return '';return `<nav class="tabs"><button class="tab ${['records','record','history'].includes(route)?'active':''}" data-go="records">${icon('file')}${financial?'报销申请':'请假申请'}</button><button class="tab" data-go="records">${icon('clock')}${financial?'付款申请':'加班申请'}</button><button class="tab" data-go="records">${icon('calendar')}${financial?'预算申请':'出勤记录'}</button><button class="plus" aria-label="新建表单" data-go="form-builder">${icon('plus')}</button><button class="tab push ${['permissions','data-permissions','app-settings'].includes(route)?'active':''}" data-go="app-settings">${icon('settings')}管理</button></nav>`}
function heading(title,sub='',actions=''){return `<div class="title-row"><h1>${title}</h1>${sub?`<span class="sub">${sub}</span>`:''}<div class="row push">${actions}</div></div>`}
function table(headers,rows,extra=''){return `<div class="tablewrap"><table class="generic ${extra}"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(c=>`<tr>${c.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function pagination(count=128){return `<div class="pagination"><span>显示第 1–10 条，共 ${count} 条</span><span class="push pagesize">10 条 / 页⌄</span><button class="page" aria-label="上一页" data-page="prev">${icon('left')}</button>${[1,2,3].map((n,i)=>`<button class="page ${!i?'active':''}" data-page="${n}">${n}</button>`).join('')}<span>…</span><button class="page" data-page="13">13</button><button class="page" aria-label="下一页" data-page="next">${icon('right')}</button></div>`}
function search(placeholder='搜索记录…'){return `<div class="searchbox">${icon('search')}<input id="localSearch" placeholder="${placeholder}" aria-label="${placeholder}"></div>`}
function tools(primary='新建记录',action='data-go="new-record"'){return `<div class="page-tools"><div class="segmented"><button class="active" data-segment="all">全部记录 <span>128</span></button><button data-segment="pending">审批中 <span>8</span></button><button data-segment="mine">我发起的 <span>12</span></button></div>${search()}${modalbtn(activeFilter||'筛选','filters','','filter')}${modalbtn('排序','sort','','sort')}${modalbtn('','columns','','columns')}${btn(primary,action,'primary','plus')}</div>`}
function home(){return `<div class="home-head"><div class="hgroup"><div class="eyebrow">MONDAY, OCTOBER 05</div><h1>下午好，宇凡</h1><p>从这里，开始今天的工作</p></div>${goto('新建记录','new-record','primary','plus')}</div><div class="grid4">${[['待我审批','8','3 项今天收到','inbox'],['我发起的','12','4 项正在审批','clock'],['我的草稿','2','最近编辑 · 14:32','file'],['常用应用','6','一切井井有条','grid']].map(([a,b,c,d])=>`<div class="card metric"><div class="metric-top">${a}${icon(d)}</div><strong>${b}</strong><span class="caption">${c}</span></div>`).join('')}</div><div class="home-grid"><div class="card"><div class="card-top"><h2>待办事项</h2><button class="muted" data-go="inbox">查看全部 ${icon('right')}</button></div>${[['林晓','差旅费用报销','财务管理 · 报销申请','¥ 2,480.00'],['陈思远','国庆后调休申请','人事管理 · 请假申请','1 天'],['许知言','华南客户拜访费用','财务管理 · 报销申请','¥ 860.00'],['周予安','设备采购申请','行政管理 · 采购申请','¥ 3,600.00'],['苏晓','个人年假申请','人事管理 · 请假申请','3 天']].map(([n,t,s,v],i)=>`<div class="list-item" data-go="approval"><span class="avatar a${i%4}">${n[0]}</span><div class="list-main"><strong>${t}</strong><small>${n} · ${s}</small></div><span class="time">${v}</span><span class="muted">${icon('right')}</span></div>`).join('')}</div><div class="stack"><div class="card"><div class="card-top"><h2>常用应用</h2><button class="muted" data-go="apps">${icon('grid')}</button></div>${[['人事管理','users','12 个表单'],['财务管理','wallet','8 个表单'],['客户管理','briefcase','6 个表单']].map(([t,i,s])=>`<div class="quickapp" data-go="application"><span class="appmark ${i==='users'?'accent':''}">${icon(i)}</span><div><strong>${t}</strong><small>${s}</small></div><span class="push muted">${icon('right')}</span></div>`).join('')}</div><div class="card light"><div class="card-top"><h2>继续编辑</h2>${icon('file')}</div><div class="list-main"><strong>十月差旅费用报销</strong><small>草稿 · 今天 14:32</small></div><div class="quick-links">${goto('打开草稿','new-record','','right')}</div></div></div></div>`}
function apps(){return heading('应用中心','12 个应用',modalbtn('导入模板','import','','upload')+modalbtn('新建应用','new-app','primary','plus'))+`<div class="page-tools"><div class="segmented"><button class="active">全部应用</button><button>我创建的</button><button>已固定</button></div>${search('搜索应用…')}</div><div class="section-row">${icon('folder')}企业管理<span class="muted">6</span><button class="push dots" data-modal="app-menu">${icon('more')}</button></div><div class="grid3">${[['人事管理','users','人员档案、假勤与入离职','12 个表单 · 4 个流程'],['财务管理','wallet','报销、预算与付款','8 个表单 · 6 个流程'],['客户管理','briefcase','客户、商机与跟进','6 个表单 · 3 个流程'],['行政管理','folder','采购、资产与日常事务','9 个表单 · 5 个流程'],['绩效管理','spark','目标、考核与反馈','5 个表单 · 2 个流程'],['项目管理','layers','项目、任务与交付','7 个表单 · 3 个流程']].map(([t,i,d,s],n)=>`<article class="card app-card" data-go="application"><span class="appmark ${n===0?'accent':''}">${icon(i)}</span><button class="pin ${n<3?'active':''}" data-pin="true" aria-label="${n<3?'取消固定':'固定应用'}">${icon('pin')}</button><h2>${t}</h2><p>${d}</p><div class="bottom">${s}<div class="mini-avatar-group push"><span class="avatar">梁</span><span class="avatar a2">林</span></div></div></article>`).join('')}</div><div class="section-row">${icon('folder')}个人空间<span class="muted">2</span></div><div class="grid3"><article class="card app-card" data-go="records"><span class="appmark">${icon('file')}</span><h2>个人工作记录</h2><p>把工作进展留在这里</p><div class="bottom">3 个表单</div></article><article class="card app-card" data-modal="new-app" style="border-style:dashed;display:grid;place-items:center"><span class="muted">${icon('plus')} 创建一个应用</span></article></div>`}
function application(){return heading('人事管理','12 个表单',goto('应用设置','app-settings','','settings')+goto('新建表单','form-builder','primary','plus'))+`<div class="grid3">${[['人员档案','users','4 个表单'],['假勤管理','calendar','3 个表单'],['入离职管理','folder','5 个表单']].map(([t,i,s])=>`<div class="card folder-card" data-go="records"><span class="appmark">${icon(i)}</span><div><h2>${t}</h2><small>${s}</small></div><span class="push muted">${icon('right')}</span></div>`).join('')}</div><div class="section-row">${icon('folder')}假勤管理</div>${table(['表单','记录数','关联流程','最近更新',''],[['请假申请','128',badge('请假审批'),'今天 14:30',goto('打开','records','','right')],['加班申请','86',badge('加班审批'),'今天 11:42',goto('打开','records','','right')],['出勤记录','2,840',badge('未绑定','outline'),'昨天 18:00',goto('打开','records','','right')]].map(r=>[`<div class="row">${icon('file')}<strong class="record">${r[0]}</strong></div>`,...r.slice(1)]))}<div class="section-row">${icon('folder')}人员档案</div>${table(['表单','记录数','关联流程','最近更新',''],[['成员信息','64',badge('未绑定','outline'),'今天 09:25',goto('打开','members','','right')],['劳动合同','58',badge('合同审批'),'10/02 16:12',goto('打开','records','','right')],['培训记录','32',badge('培训审批'),'09/30 15:20',goto('打开','records','','right')]])}`}
function recordsPage(){return heading('请假申请','128 条记录',goto('编辑表单','form-builder','','edit'))+tools()+`<div id="recordTable">${recordTable(records)}</div>${pagination()}`}
function recordTable(list){return table([check(false),'申请事由','申请人','请假类型','请假日期','时长','审批状态',''],list.map((r,i)=>[check(false),`<button class="record" data-go="record" style="text-align:left;padding:0">${r[0]}<small>LV-2026-${String(128-i).padStart(4,'0')}</small></button>`,person(r[1],'a'+i%4),r[2],r[3],r[4],badge(r[5],r[5]==='已通过'?'done':''),`<button class="dots" data-modal="record-menu" aria-label="记录操作">${icon('more')}</button>`]))}
function field(label,value,opts={}){return `<div class="field ${opts.full?'full':''}"><label>${label}${opts.required?'<span class="required">*</span>':''}</label>${opts.input?`<input aria-label="${label}" value="${esc(value)}" ${opts.disabled?'disabled':''}>`:`<div class="value ${opts.money?'money':''}">${value}</div>`}</div>`}
function expenseForm(edit=false,approval=false){return `<div class="form-grid">${field('申请人','梁宇凡',{input:edit,disabled:approval})}${field('申请日期','2026 / 10 / 05',{input:edit,disabled:approval})}${field('所属部门','产品研发部',{input:edit,disabled:approval})}${field('费用类型','差旅费用',{input:edit,disabled:approval})}${field('报销金额',edit?'2,480.00':'¥ 2,480.00',{input:edit,money:!edit,required:edit})}${field('票据张数','4',{input:edit,required:edit})}<div class="field full"><label>报销事由</label>${edit?`<textarea aria-label="报销事由" ${approval?'disabled':''}>华南客户项目沟通，交通与住宿费用。</textarea>`:'<div class="value">华南客户项目沟通，交通与住宿费用。</div>'}</div><div class="field full"><label>票据附件</label><div class="row wrap"><span class="file-chip">${icon('file')}交通发票.pdf <span class="muted">128 KB</span></span><span class="file-chip">${icon('file')}住宿发票.pdf <span class="muted">256 KB</span></span></div></div>${field('备注','费用明细已附在票据中',{full:true,input:edit,disabled:approval})}</div>`}
function timeline(){return `<div class="timeline"><div class="timeline-item"><span class="timeline-icon">${icon('check')}</span><strong>发起申请</strong><p>梁宇凡 · 今天 09:42</p></div><div class="timeline-item"><span class="timeline-icon">${icon('check')}</span><strong>部门经理</strong><p>陈思远 · 今天 10:18</p><div class="note">同意</div></div><div class="timeline-item current"><span class="timeline-icon">${icon('clock')}</span><strong>财务审批</strong><p>林晓 · 等待审批</p></div><div class="timeline-item"><span class="timeline-icon">${icon('wallet')}</span><strong>出纳打款</strong><p>许知言</p></div></div>`}
