function newRecord(){return heading('新建报销','财务管理 / 报销申请',btn('退出','data-exit="true"'))+`<div style="max-width:850px;margin:auto"><div class="card form-card">${expenseForm(true)}<div class="form-footer"><span class="demo-note" style="margin-right:auto;align-self:center">草稿仅保存在当前浏览器</span>${btn('保存草稿','data-save="draft"')}${modalbtn('提交','submit','primary')}</div></div></div>`}
function designer(){return `<div class="editor-center"><div class="paper" id="formPaper"><div class="form-grid">${[['申请人','梁宇凡'],['申请日期','2026 / 10 / 05'],['费用类型','请选择'],['所属部门','请选择'],['报销金额','请输入金额'],['票据张数','请输入数量'],['报销事由','填写报销事由'],['票据附件','上传票据'],['备注','选填']].map(([l,v],i)=>`<div class="field design-field ${i>5?'full':''} ${l===selectedField?'active':''}" data-select-field="${l}"><span class="grip">${icon('grip')}</span><label>${l}${i<7?'<span class="required">*</span>':''}</label>${i===7?`<div class="attachment">${icon('upload')}点击或拖入文件</div>`:i===6?`<textarea placeholder="${v}"></textarea>`:`<input placeholder="${v}">`}</div>`).join('')}</div><div class="drop-slot" id="dropField">${icon('plus')} 拖入字段</div></div></div><aside class="properties"><div class="row between" style="margin-bottom:24px"><h2 style="margin:0">字段属性</h2><span class="small-label">${icon('number')}</span></div><div class="field"><label>字段名称</label><input id="fieldName" value="${selectedField}" aria-label="字段名称"></div><div class="field"><label>字段类型</label><select aria-label="字段类型"><option>${selectedField.includes('金额')?'金额':'单行文字'}</option><option>数字</option><option>日期</option></select></div><div class="field"><label>占位提示</label><input value="请输入金额" aria-label="占位提示"></div><div class="thin-separator"></div><div class="property-sub">数值格式</div><div class="field"><label>小数位数</label><select><option>2 位</option><option>0 位</option><option>4 位</option></select></div><div class="field"><label>舍入规则</label><select><option>四舍五入</option><option>向零取整</option><option>自定义抹零</option></select></div><div class="field"><label>单位</label><input value="元"></div><div class="thin-separator"></div><div class="property-row">必填 ${toggle()}</div><div class="property-row">默认值 ${toggle(false)}</div><div class="property-row">输入校验 ${toggle(false)}</div><div class="thin-separator"></div>${btn('删除字段','data-remove-field="true"','danger','trash')}</aside>`}
