function flowDesigner(){return `<div class="flow-canvas"><div class="flow-track"><div class="terminus">开始</div><div class="connector"></div>${[['提交申请','发起人','users'],['部门经理','陈思远 · 单人审批','shield'],['财务审批','林晓 · 单人审批','wallet'],['出纳打款','许知言 · 单人审批','check']].map(([n,s,i])=>`<div class="flow-node ${selectedNode===n?'selected':''}" data-select-node="${n}"><div class="row"><span class="node-icon">${icon(i)}</span><strong>${n}</strong><span class="push muted">${icon('more')}</span></div><small>${s}</small></div><div class="connector"><button data-modal="add-node" aria-label="添加节点">${icon('plus')}</button></div>`).join('')}<div class="terminus">结束</div></div><div class="canvas-tools"><button aria-label="缩小">${icon('minimize')}</button><span>100%</span><button aria-label="放大">${icon('plus')}</button><span style="padding:0 7px">适应画布</span></div></div><aside class="properties"><h2>${selectedNode}</h2><div class="field"><label>节点名称</label><input value="${selectedNode}"></div><div class="field"><label>审批人</label><div class="row" style="border:1px solid #e7e1ed;border-radius:7px;padding:9px">${person('林晓')}<button class="push muted" data-modal="approvers">${icon('plus')}</button></div></div><div class="field"><label>多人审批方式</label><select><option>全部同意</option><option>任意一人同意</option></select></div><div class="thin-separator"></div><div class="property-sub">可编辑字段</div>${['申请人','申请日期','报销金额','票据张数','报销事由','备注'].map((t,i)=>`<label class="property-row">${t}${check(i===2||i===3)}</label>`).join('')}<div class="thin-separator"></div><div class="property-row">允许退回已走过节点 ${toggle()}</div><div class="property-row">审批备注必填 ${toggle(false)}</div></aside>`}
